export function identifyMultisigProgramAccount(
	account: { data: ReadonlyUint8Array } | ReadonlyUint8Array,
): MultisigProgramAccount {
	const data = "data" in account ? account.data : account;
	if (
		containsBytes(data, getU8Encoder().encode(1), 0) &&
		containsBytes(data, getU8Encoder().encode(0), 1)
	) return MultisigProgramAccount.ProgramConfig;
	if (
		containsBytes(data, getU8Encoder().encode(2), 0) &&
		containsBytes(data, getU8Encoder().encode(0), 1)
	) return MultisigProgramAccount.Multisig;
	if (
		containsBytes(data, getU8Encoder().encode(3), 0) &&
		containsBytes(data, getU8Encoder().encode(0), 1)
	) return MultisigProgramAccount.Proposal;
	if (
		containsBytes(data, getU8Encoder().encode(4), 0) &&
		containsBytes(data, getU8Encoder().encode(0), 1)
	) return MultisigProgramAccount.SpendingLimit;
	throw new SolanaError(
		SOLANA_ERROR__PROGRAM_CLIENTS__FAILED_TO_IDENTIFY_ACCOUNT,
		{ accountData: data, programName: "multisigProgram" },
	);
}

